-- Nota no artigo "Aprovar os posts orgânicos automáticos (Central de Redes Sociais)": botões de ação do painel de aprovação (04/10/2026).
-- Não repete se rodar de novo (a condição olha se a nota já está lá).
UPDATE public.ajuda_conteudos
SET como_utilizar = como_utilizar || E'\n\nAtualização de 04/10/2026 — botões de ação em todos os posts (aba "Aprovações"):\n- Cada cartão mostra a rede (Instagram e/ou Facebook), o formato (por exemplo "Carrossel · 10 fotos"), todas as fotos do post e a legenda completa.\n- "Aprovar" (posts em Rascunho): coloca o post na fila. Ele sai em até 15 minutos e a tela avisa quando sair.\n- "Editar" (Rascunho, Agendado e Erro): muda a legenda, a data e a hora de publicação e, no carrossel, tira fotos clicando no X (mínimo 2 fotos). Clique em "Salvar".\n- "Excluir": apaga o post da fila (pede confirmação). Num post já publicado, ele só sai desta lista; a publicação continua no Instagram e no Facebook e precisa ser apagada lá.\n- "Publicar novamente": em post com erro, tenta de novo (zera as tentativas). Em post já publicado, cria um post novo igual na fila (pede confirmação e avisa que o conteúdo aparecerá duas vezes nas redes).\n- Enquanto o post está "Publicando", os botões somem até terminar.\n- Posts do orgânico diário antigo podem começar com um texto de introdução da IA ("Aqui está o post..."): use "Editar" para apagar essa frase ou "Excluir".'
WHERE titulo = 'Aprovar os posts orgânicos automáticos (Central de Redes Sociais)'
  AND como_utilizar NOT LIKE '%Atualização de 04/10/2026%';
